      $('#cf-canal', root) && ($('#cf-canal', root).onclick = () => L.modal({ title: `Canal de avisos · ${c.nombre}`, body: `<p class="muted" style="margin-top:0">Buena parte del canal tradicional no usa correo: el aviso de despacho y de llegada se envía por el canal que el cliente prefiera.</p><fieldset><legend class="sr-only">Canal</legend>${['Mensaje de texto (SMS)', 'WhatsApp', 'Correo electrónico', 'Llamada del preventista'].map((x) => `<label class="radio"><input type="radio" name="cv" value="${x}" ${x === L.canalAviso(c) ? 'checked' : ''}> ${x}</label>`).join('')}</fieldset>`, actions: [{ label: 'Cancelar' }, { label: 'Guardar', cls: 'btn-primary', onClick: (api) => { const v = $('[name=cv]:checked', api.el).value; L.logAudit('Modificación', 'Cliente', `Canal de avisos de ${c.nombre}`, 'Consola web', L.canalAviso(c), v); L.store.set('canal.' + c.id, v); L.toast('Canal actualizado', `${c.nombre} recibirá los avisos por ${v}.`, 'success'); L.router.resolve(); } }] }));
      $$('[data-dl]', root).forEach((b) => (b.onclick = () => { const d = D.devoluciones.find((x) => x.id === b.dataset.nc); if (d) L.downloadDemoText(d.id, 'Resumen de devolución', { Producto: d.producto, Unidades: d.cant, Lote: d.lote, Motivo: d.motivo, Estado: d.estado }); }));
